    "html": "<!-- label: Cheat Sheet | description: Dense multi-column sheet that prints cleanly. Practice cards and quiz sit below and are skipped when printing. -->\n<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>{{title}}</title>\n{{>style}}\n<style>\n  body{padding:16px 12px;font-size:14px;line-height:1.45}\n  .wrap{max-width:1100px}\n  header{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;border-bottom:3px solid var(--acc);padding-bottom:8px;margin-bottom:14px}\n  header h1{font-size:24px;margin:0}header .sum{font-size:13px}\n  .sheet{column-width:290px;column-gap:14px}\n  .sheet>*{break-inside:avoid;margin-bottom:12px}\n  .card{padding:10px 12px;border-radius:10px;margin-bottom:12px}\n  .card h2{font-size:15px;margin:0 0 6px;text-transform:uppercase;letter-spacing:.6px}\n  li{margin:2px 0}.abbr{grid-template-columns:1fr}.ab{padding:4px 8px}.trick{font-size:16px}\n  .tbl th,.tbl td{padding:4px 6px;font-size:13px}\n  dt{margin-top:6px}dd{font-size:13px}\n  .practice{margin-top:22px}\n  @media print{body{background:#fff;color:#000;padding:0}.card{border-color:#999}.practice{display:none}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header><h1>{{title}}</h1>{{#hasSummary}}<span class=\"sum\">{{summary}}</span>{{/hasSummary}}</header>\n  <div class=\"sheet\">\n    {{>keyfacts}}\n    {{>abbreviations}}\n    {{>terms}}\n    {{#sections}}<section class=\"card\" data-rv><h2>{{heading}}</h2><ul>{{#points}}<li>{{.}}</li>{{/points}}</ul></section>{{/sections}}\n    {{>comparisons}}\n    {{>mnemonics}}\n    {{>timeline}}\n    {{>traps}}\n    {{>examples}}\n  </div>\n  <div class=\"practice\">{{>flashcards}}{{>quiz}}</div>\n</div>\n{{>script}}\n</body>\n</html>\n"
