    "html": "<!-- label: Notebook | description: Lined-paper look with a margin line, sticky-note cheat sheet and handwritten-style headings. -->\n<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>{{title}}</title>\n{{>style}}\n<style>\n  .paper{max-width:820px;margin:auto;background:var(--card);border:1px solid var(--line);border-radius:6px 16px 16px 6px;padding:28px 26px 28px 64px;position:relative;\n    background-image:repeating-linear-gradient(transparent 0,transparent 31px,var(--line) 31px,var(--line) 32px);box-shadow:0 6px 24px rgba(0,0,0,.08)}\n  .paper:before{content:\"\";position:absolute;left:44px;top:0;bottom:0;width:2px;background:var(--acc);opacity:.5}\n  .paper:after{content:\"\";position:absolute;left:14px;top:30px;bottom:30px;width:12px;background:radial-gradient(circle,var(--bg) 5px,transparent 6px) 0 0/12px 56px repeat-y}\n  h1{font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:32px;margin:0 0 4px}\n  .paper h2{font-family:Georgia,'Times New Roman',serif;font-style:italic;color:var(--acc);font-size:21px;margin:22px 0 6px}\n  .paper .card{background:transparent;border:0;border-radius:0;padding:0;margin:0 0 6px}\n  .paper .card h2{color:var(--acc)}\n  .paper ul{line-height:32px;margin:0}.paper li{margin:0}\n  .paper dt,.paper dd{line-height:32px;margin:0}\n  .sticky{background:#fff7a8;color:#3b3200;border-radius:2px;padding:12px 16px;transform:rotate(-.6deg);box-shadow:2px 4px 10px rgba(0,0,0,.18);margin:18px 0}\n  .sticky h2{color:#3b3200;margin:0 0 4px}.sticky ul{line-height:1.5}\n  .paper .ab,.paper .mn,.paper .exm{background:transparent}\n  .paper .fc,.paper .q{background:var(--card)}\n  .tape{display:block;width:90px;height:22px;margin:-34px auto 14px;background:rgba(255,255,255,.55);border:1px solid var(--line);transform:rotate(-2deg)}\n</style>\n</head>\n<body>\n<div class=\"paper\">\n  <span class=\"tape\"></span>\n  <h1>{{title}}</h1>\n  {{#hasSummary}}<p class=\"sum\">{{summary}}</p>{{/hasSummary}}\n\n  {{#has.keyFacts}}<div class=\"sticky\">{{>keyfacts}}</div>{{/has.keyFacts}}\n\n  {{#sections}}<div class=\"nb\" data-rv><h2>{{heading}}</h2><ul>{{#points}}<li>{{.}}</li>{{/points}}</ul></div>{{/sections}}\n  {{^sections}}<p class=\"sum\">No notes sections were generated.</p>{{/sections}}\n\n  {{>terms}}\n  {{>abbreviations}}\n  {{>mnemonics}}\n  {{>comparisons}}\n  {{>timeline}}\n  {{>traps}}\n  {{>examples}}\n  {{>flashcards}}\n  {{>quiz}}\n</div>\n{{>script}}\n</body>\n</html>\n"
